#!/usr/bin/env python3
"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import re
import sys


def nid(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = "".join(ch if ch.isalnum() else " " for ch in s)
    return " ".join(s.split())


# ---------------------------------------------------------------- reading

def parse_csv(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    meta = {}
    pos = 0
    n = len(text)
    # leading comment / blank lines
    while pos < n:
        end = text.find("\n", pos)
        if end < 0:
            end = n
        line = text[pos:end].rstrip("\r")
        if line.strip() == "":
            pos = end + 1
            continue
        if line.startswith("#"):
            body = line[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta[k.strip().lower()] = v.strip()
            pos = end + 1
            continue
        break
    rest = text[pos:]
    reader = csv.reader(io.StringIO(rest, newline=""))
    header = None
    records = []
    for row in reader:
        if not row or all(c.strip() == "" for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        d = {}
        for i, name in enumerate(header):
            if i < len(row):
                d[name] = row[i]
        ranks = {}
        for name, val in d.items():
            m = re.fullmatch(r"rank(\d+)", name)
            if m and val.strip() != "":
                marks = []
                for piece in val.split("|"):
                    p = piece.strip()
                    if p == "":
                        continue
                    if p.startswith("WI:"):
                        marks.append(("w", p[3:]))
                    else:
                        marks.append(("c", p))
                ranks[int(m.group(1))] = marks
        records.append((d.get("ballot", ""), d.get("contest", ""), ranks))
    return meta, records


def parse_jsonl(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    meta = None
    records = []
    for line in text.split("\n"):
        if line.strip() == "":
            continue
        obj = json.loads(line)
        if meta is None:
            meta = {str(k).lower(): v for k, v in obj.items()}
            continue
        ranks = {}
        for mk in obj.get("marks", []) or []:
            r = int(mk["rank"])
            if "candidate" in mk and mk["candidate"] is not None:
                ranks.setdefault(r, []).append(("c", str(mk["candidate"]).strip()))
            elif "write_in" in mk and mk["write_in"] is not None:
                ranks.setdefault(r, []).append(("w", str(mk["write_in"])))
        records.append((obj.get("ballot", ""), obj.get("contest", ""), ranks))
    return meta or {}, records


def load_batches(indir):
    cvr = os.path.join(indir, "cvr")
    best = {}  # batch id -> (revision, status, records)
    if not os.path.isdir(cvr):
        return []
    for name in sorted(os.listdir(cvr)):
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        with open(path, "rb") as f:
            text = f.read().decode("utf-8")
        if name.endswith(".csv"):
            meta, recs = parse_csv(text)
        else:
            meta, recs = parse_jsonl(text)
        batch = str(meta.get("batch", ""))
        rev = int(str(meta.get("revision", "1")).strip())
        status = str(meta.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status == "void":
            continue
        out.extend(recs)
    return out


# --------------------------------------------------------------- counting

SKIP, PASS, CHOICE, OVER = "skip", "pass", "choice", "over"


def read_ballot(ranks, contest):
    """Return list of (kind, candidate-or-None) per ranking 1..max_ranks."""
    maxr = contest["max_ranks"]
    wi = contest["wi_lookup"]
    withdrawn = contest["withdrawn"]
    seen = set()
    result = []
    for r in range(1, maxr + 1):
        marks = ranks.get(r, [])
        cands = []
        for kind, val in marks:
            if kind == "w":
                c = wi.get(norm_text(val))
                if c is None:
                    continue
            else:
                c = nid(val)
            if c not in cands:
                cands.append(c)
        if not cands:
            result.append((SKIP, None))
            continue
        cands = [c for c in cands if c not in withdrawn]
        if not cands:
            result.append((PASS, None))
            continue
        after_b = list(cands)
        cands = [c for c in cands if c not in seen]
        seen.update(after_b)
        if not cands:
            result.append((SKIP, None))
            continue
        if len(cands) == 1:
            result.append((CHOICE, cands[0]))
        else:
            result.append((OVER, None))
    return result


def count_for(ballot, continuing):
    """Candidate the ballot counts for, or None when exhausted."""
    n = len(ballot)
    for i in range(n):
        kind, c = ballot[i]
        if kind == CHOICE:
            if c in continuing:
                return c
        elif kind == PASS:
            continue
        elif kind == OVER:
            return None
        else:  # SKIP
            if i + 1 >= n or ballot[i + 1][0] == SKIP:
                return None
    return None


def run_contest(contest, records):
    ballots = [read_ballot(r, contest) for r in records]
    total = len(ballots)
    cand_ids = contest["continuing_ids"]  # normalized ids in output order
    display = contest["display"]
    lot_pos = contest["lot_pos"]
    continuing = set(cand_ids)
    rounds = []
    history = []  # list of dict norm id -> votes
    winner = None
    rnd = 0
    while True:
        rnd += 1
        votes = {c: 0 for c in continuing}
        active = 0
        for b in ballots:
            c = count_for(b, continuing)
            if c is not None:
                votes[c] += 1
                active += 1
        history.append(votes)
        entry = {
            "round": rnd,
            "tallies": {display[c]: votes[c] for c in sorted(continuing, key=lambda x: display[x])},
            "exhausted": total - active,
            "eliminated": [],
        }
        rounds.append(entry)
        if active == 0:
            break
        win = None
        for c in continuing:
            if votes[c] * 2 > active:
                win = c
        if win is None and len(continuing) == 1:
            win = next(iter(continuing))
        if win is not None:
            winner = display[win]
            break
        zeros = [c for c in continuing if votes[c] == 0]
        if zeros:
            elim = zeros
        else:
            low = min(votes.values())
            tied = [c for c in continuing if votes[c] == low]
            k = len(history) - 2
            while len(tied) > 1 and k >= 0:
                m = min(history[k][c] for c in tied)
                tied = [c for c in tied if history[k][c] == m]
                k -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lot_pos.get(c, -1))]
            elim = tied
        entry["eliminated"] = sorted(display[c] for c in elim)
        continuing = continuing - set(elim)
        if not continuing:
            break
    return {"contest": contest["id"], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, "election.json"), "rb") as f:
        election = json.loads(f.read().decode("utf-8"))
    contests = {}
    order = []
    for c in election.get("contests", []):
        display = {}
        withdrawn = set()
        cont = []
        for cand in c.get("candidates", []):
            k = nid(cand["id"])
            display[k] = cand["id"]
            if cand.get("status", "active") == "withdrawn":
                withdrawn.add(k)
            else:
                cont.append(k)
        wi_lookup = {}
        for w in c.get("write_ins", []):
            k = nid(w["id"])
            display[k] = w["id"]
            cont.append(k)
            for t in [w.get("name", "")] + list(w.get("aliases", [])):
                wi_lookup.setdefault(norm_text(t), k)
        lot_pos = {nid(x): i for i, x in enumerate(c.get("lot_order", []))}
        contests[c["id"]] = {
            "id": c["id"],
            "max_ranks": int(c.get("max_ranks", 0)),
            "display": display,
            "withdrawn": withdrawn,
            "continuing_ids": cont,
            "wi_lookup": wi_lookup,
            "lot_pos": lot_pos,
            "records": [],
        }
        order.append(c["id"])
    for ballot, cid, ranks in load_batches(indir):
        if cid in contests:
            contests[cid]["records"].append(ranks)
    out = {"election": election.get("election"), "contests": []}
    for cid in order:
        c = contests[cid]
        out["contests"].append(run_contest(c, c["records"]))
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
